//! REF-009 / DEP-010: the typed conversions of `ferroastro-time` (and the ERFA port under them)
//! against pyerfa 2.0.1.5 goldens at 223 epochs spanning 1550-2650, in f64 and double-double.
//!
//! Oracles: `tests/goldens/erfa-time-pyerfa.csv` (generated by `tools/goldens/erfa_time.py`,
//! pinned by SHA-256) and the tolerances of vectors `PYERFA-*` in `tests/vectors/time-scales.toml`.
#![allow(
    clippy::unwrap_used,
    clippy::panic,
    reason = "test helpers: a failed unwrap is a test failure with a clear message"
)]

mod common;

use common::{Golden, load, vectors};
use ferroastro_erfa::{dtdb, jd2cal};
use ferroastro_real::{DoubleDouble, Real};
use ferroastro_time::{Convert, Epoch, Tai, Tcb, Tcg, Tdb, TimeScale, Tt};
use ferroastro_vectors::VectorSet;

const TABLE: &str = "erfa-time-pyerfa.csv";

/// Running maximum with the row (year) where it occurred.
#[derive(Default)]
struct Max {
    value: f64,
    year: i32,
}

impl Max {
    fn add(&mut self, x: f64, year: i32) {
        assert!(x.is_finite());
        if x > self.value {
            *self = Max { value: x, year };
        }
    }
}

fn epoch<S: TimeScale, R: Real>(g: &Golden, row: &[String], c1: &str, c2: &str) -> Epoch<S, R> {
    Epoch::from_jd_parts(R::from_f64(g.f(row, c1)), R::from_f64(g.f(row, c2))).unwrap()
}

/// |ours − golden| in seconds, part by part.
fn sec<S: TimeScale, R: Real>(
    ours: Epoch<S, R>,
    g: &Golden,
    row: &[String],
    c1: &str,
    c2: &str,
) -> f64 {
    let (o1, o2) = ours.jd_parts();
    let d = (o1 - R::from_f64(g.f(row, c1))) + (o2 - R::from_f64(g.f(row, c2)));
    (d * R::from_f64(86_400.0)).abs().to_f64() // lint: allow-literal(seconds per day)
}

fn check(v: &VectorSet, id: &str, backend: &str, m: &Max) {
    let vector = v.get(id).unwrap();
    println!(
        "{id:<26} {backend:<14} max |diff| {:.3e} {} (at year {})",
        m.value, vector.unit, m.year
    );
    if let Err(e) = vector.check(m.value) {
        panic!("{backend}: {e}");
    }
}

fn run<R: Real>(v: &VectorSet) {
    let g = load(TABLE, v, "PYERFA-TT-TDB-MAX-DIFF");
    assert!(g.rows.len() >= 200, "REF-009/WP8: at least 200 epochs");
    let b = R::NAME;
    let [mut tai, mut tdb, mut tcb, mut tcg, mut w, mut fd] =
        std::array::from_fn(|_| Max::default());
    let (mut ymin, mut ymax) = (i32::MAX, i32::MIN);
    for row in &g.rows {
        let year = g.i(row, "iy");
        ymin = ymin.min(year);
        ymax = ymax.max(year);
        let tt: Epoch<Tt, R> = epoch(&g, row, "tt1", "tt2");

        // TT <-> TAI
        let o: Epoch<Tai, R> = tt.to_scale().unwrap();
        tai.add(sec(o, &g, row, "tai1", "tai2"), year);
        let o: Epoch<Tt, R> = epoch::<Tai, R>(&g, row, "tai1", "tai2").to_scale().unwrap();
        tai.add(sec(o, &g, row, "tt_from_tai1", "tt_from_tai2"), year);

        // TT <-> TDB
        let o: Epoch<Tdb, R> = tt.to_scale().unwrap();
        tdb.add(sec(o, &g, row, "tdb1", "tdb2"), year);
        let o: Epoch<Tt, R> = epoch::<Tdb, R>(&g, row, "tdb1", "tdb2").to_scale().unwrap();
        tdb.add(sec(o, &g, row, "tt_from_tdb1", "tt_from_tdb2"), year);

        // TDB <-> TCB (from pyerfa's TDB, so this isolates the TCB step)
        let o: Epoch<Tcb, R> = epoch::<Tdb, R>(&g, row, "tdb1", "tdb2").to_scale().unwrap();
        tcb.add(sec(o, &g, row, "tcb1", "tcb2"), year);
        let o: Epoch<Tdb, R> = epoch::<Tcb, R>(&g, row, "tcb1", "tcb2").to_scale().unwrap();
        tcb.add(sec(o, &g, row, "tdb_from_tcb1", "tdb_from_tcb2"), year);

        // TT <-> TCG
        let o: Epoch<Tcg, R> = tt.to_scale().unwrap();
        tcg.add(sec(o, &g, row, "tcg1", "tcg2"), year);
        let o: Epoch<Tt, R> = epoch::<Tcg, R>(&g, row, "tcg1", "tcg2").to_scale().unwrap();
        tcg.add(sec(o, &g, row, "tt_from_tcg1", "tt_from_tcg2"), year);

        // dtdb, geocentric and topocentric
        let r = |c: &str| R::from_f64(g.f(row, c));
        let (t1, t2) = (r("tt1"), r("tt2"));
        let geo = dtdb(t1, t2, R::ZERO, R::ZERO, R::ZERO, R::ZERO);
        w.add((geo - r("dtdb_geo")).abs().to_f64(), year);
        let topo = dtdb(t1, t2, r("ut"), r("elong"), r("u"), r("v"));
        w.add((topo - r("dtdb_topo")).abs().to_f64(), year);

        // jd2cal
        let cal = jd2cal(t1, t2).unwrap();
        assert_eq!(
            (cal.year, cal.month, cal.day),
            (g.i(row, "cal_iy"), g.i(row, "cal_im"), g.i(row, "cal_id")),
            "{b}: jd2cal date at row {row:?}"
        );
        fd.add((cal.fraction - r("cal_fd")).abs().to_f64(), year);
    }
    println!("{b}: {} epochs, years {ymin}..={ymax}", g.rows.len());
    check(v, "PYERFA-TT-TAI-MAX-DIFF", b, &tai);
    check(v, "PYERFA-TT-TDB-MAX-DIFF", b, &tdb);
    check(v, "PYERFA-TDB-TCB-MAX-DIFF", b, &tcb);
    check(v, "PYERFA-TT-TCG-MAX-DIFF", b, &tcg);
    check(v, "PYERFA-DTDB-MAX-DIFF", b, &w);
    check(v, "PYERFA-JD2CAL-FD-MAX-DIFF", b, &fd);
}

/// Verifies: REF-009, DEP-010, DEP-009
#[test]
fn pyerfa_goldens_f64() {
    run::<f64>(&vectors());
}

/// Verifies: REF-009, DEP-010, DEP-007
#[test]
fn pyerfa_goldens_double_double() {
    run::<DoubleDouble>(&vectors());
}
